#include <stdio.h>

#define V 4
#define INF 1000000

int d[V][V];
int path[V][V];

int main(void) {
    int init[V][V] = {
        {0,   3,   INF, 7},
        {8,   0,   2,   INF},
        {5,   INF, 0,   1},
        {2,   INF, INF, 0}
    };
    for (int i = 0; i < V; i++)
        for (int j = 0; j < V; j++) { d[i][j] = init[i][j]; path[i][j] = -1; }

    printf("初始距离矩阵：\n");
    for (int i = 0; i < V; i++) {
        for (int j = 0; j < V; j++) {
            if (d[i][j] >= INF) printf(" INF ");
            else printf("%4d ", d[i][j]);
        }
        printf("\n");
    }

    /* k 必须在最外层：d_k[i][j] = 只允许经过前 k 个点中转的最短路 */
    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                if (d[i][k] + d[k][j] < d[i][j]) {
                    d[i][j] = d[i][k] + d[k][j];
                    path[i][j] = k;
                }
            }
        }
        printf("\n允许经过前 %d 个点（0..%d）中转后：\n", k + 1, k);
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                if (d[i][j] >= INF) printf(" INF ");
                else printf("%4d ", d[i][j]);
            }
            printf("\n");
        }
    }

    printf("\n最终全源最短路：\n");
    printf("      ");
    for (int j = 0; j < V; j++) printf("到%d ", j);
    printf("\n");
    for (int i = 0; i < V; i++) {
        printf("从%d : ", i);
        for (int j = 0; j < V; j++) {
            if (d[i][j] >= INF) printf("INF ");
            else printf("%3d ", d[i][j]);
        }
        printf("\n");
    }

    printf("\n自检：对角线应全为 0 —— ");
    int ok = 1;
    for (int i = 0; i < V; i++) if (d[i][i] != 0) ok = 0;
    printf("%s\n", ok ? "通过" : "失败");

    printf("\n要点：k 是阶段变量，放最外层才能保证转移用到上一阶段的值。\n");
    printf("      写成 i->j->k 会静默给错结果（不崩溃），是最难排查的一类 bug。\n");
    return 0;
}
